<?php requireRole('student'); $cid=(int)($_GET['course_id']??0); ?><div id="lesson" class="card">Loading...</div><script>const courseId=<?=$cid?>;let lessons=[],i=0,phase='explanation';async function load(){lessons=await api('backend/api/course.php?action=lesson&course_id='+courseId);render()}function render(){let x=lessons[i],el=document.getElementById('lesson');if(!x){el.innerHTML='<div class="hero"><h1>🎓 Course Complete!</h1><p>Great work. Keep coding!</p><a class="btn" href="index.php?page=dashboard">Dashboard</a></div>';return}if(phase==='explanation'){el.innerHTML=`<p class="muted">Lesson ${i+1} of ${lessons.length}</p><h1>${escapeHTML(x.title)}</h1><div class="card"><h2>📚 Explanation</h2><p style="white-space:pre-wrap;line-height:1.8">${escapeHTML(x.explanation)}</p></div><div class="actions"><button class="btn" onclick="phase='question';render()">Next →</button></div>`}else{el.innerHTML=`<p class="muted">Challenge ${i+1} of ${lessons.length}</p><h1>✏️ Challenge</h1><p>${escapeHTML(x.prompt)}</p><textarea id="answer" class="code" placeholder="Write your code here..."></textarea><div id="feedback"></div><div class="actions"><button class="btn secondary" onclick="phase='explanation';render()">← Back</button><button class="btn" onclick="submitAnswer(${x.question_id})">Submit Answer</button></div>`}}async function submitAnswer(q){let f=new FormData();f.append('action','submit');f.append('question_id',q);f.append('answer',document.getElementById('answer').value);f.append('csrf',window.CSRF);try{let r=await post('backend/api/course.php',f);let m=document.getElementById('feedback');m.className='notice '+(r.correct?'success':'error');m.textContent=r.message+(r.xp?' +'+r.xp+' XP':'');if(r.correct)setTimeout(()=>{i++;phase='explanation';render()},700)}catch(e){document.getElementById('feedback').innerHTML='<div class="notice error">'+escapeHTML(e.message)+'</div>'}}load()</script>
